const getOldestStorageBillingPeriod = `-- name: GetOldestStorageBillingPeriod :one
WITH periods AS (
    SELECT DISTINCT
           retained.authorization_id,
           generate_series(
               date_trunc(
                   'day', retained.starts_at AT TIME ZONE 'UTC'
               ) AT TIME ZONE 'UTC',
               date_trunc(
                   'day',
                   (
                       LEAST(
                           COALESCE(retained.ends_at, $1),
                           $1
                       ) - interval '1 microsecond'
                   ) AT TIME ZONE 'UTC'
               ) AT TIME ZONE 'UTC',
               interval '1 day'
           ) AS period_start
    FROM realqa_storage_retention_intervals AS retained
    WHERE retained.starts_at < $1
      AND LEAST(
          COALESCE(retained.ends_at, $1),
          $1
      ) > retained.starts_at
),
unsettled AS (
    SELECT period.authorization_id, period.period_start
    FROM periods AS period
    LEFT JOIN realqa_storage_daily_settlements AS settlement
      ON settlement.authorization_id = period.authorization_id
     AND settlement.period_start = period.period_start
    WHERE settlement.authorization_id IS NULL
       OR settlement.state IN ('pending', 'reserved')
)
SELECT authorization_id,
       to_char(
           period_start AT TIME ZONE 'UTC',
           'YYYY-MM-DD"T"HH24:MI:SS"Z"'
       )::text AS period_start
FROM unsettled
ORDER BY period_start, authorization_id
LIMIT 1
`

type GetOldestStorageBillingPeriodRow struct {
	AuthorizationID pgtype.UUID
	PeriodStart     string
}

func (q *Queries) GetOldestStorageBillingPeriod(ctx context.Context, cutoff pgtype.Timestamptz) (GetOldestStorageBillingPeriodRow, error) {
	row := q.db.QueryRow(ctx, getOldestStorageBillingPeriod, cutoff)
	var i GetOldestStorageBillingPeriodRow
	err := row.Scan(&i.AuthorizationID, &i.PeriodStart)
	return i, err
}

