const resolveStorageRecovery = `-- name: ResolveStorageRecovery :one
WITH recovered AS (
    UPDATE realqa_storage_recoveries
    SET recovered_at = $1,
        updated_at = transaction_timestamp()
    WHERE realqa_storage_recoveries.submission_id =
            $2
      AND realqa_storage_recoveries.recovered_at IS NULL
      AND realqa_storage_recoveries.expired_at IS NULL
    RETURNING realqa_storage_recoveries.submission_id
)
UPDATE realqa_submissions AS submission
SET state = CASE
        WHEN submission.state = 'storage_billing_grace'
          AND EXISTS (
              SELECT 1
              FROM realqa_assets AS asset
              WHERE asset.submission_id = submission.id
                AND asset.state = 'public_retained'
          ) THEN 'submitted'
        WHEN submission.state = 'storage_billing_grace'
          THEN 'assets_deleted'
        ELSE submission.state
    END,
    updated_at = transaction_timestamp(),
    revision = revision + CASE
        WHEN submission.state = 'storage_billing_grace' THEN 1
        ELSE 0
    END
FROM recovered
WHERE submission.id = recovered.submission_id
RETURNING submission.id, submission.owner_kind, submission.owner_id, submission.created_by_account_id, submission.preset_id, submission.destination_id, submission.state, submission.provider_issue_id, submission.provider_issue_url, submission.idempotency_digest, submission.revision, submission.created_at, submission.updated_at, submission.submitted_at, submission.payer_organization_id, submission.payer_team_id, submission.preset_revision, submission.declared_encoded_bytes, submission.verified_encoded_bytes, submission.upload_deadline, submission.upload_expires_at, submission.client_idempotency_key, submission.transfer_meter_id, submission.transfer_service_identity_id, submission.transfer_reservation_id, submission.transfer_reserve_idempotency_key, submission.transfer_commit_idempotency_key, submission.transfer_release_idempotency_key, submission.transfer_reserved_units, submission.transfer_committed_units, submission.transfer_state, submission.transfer_reservation_created_at, submission.transfer_reservation_expires_at
`

